const orders = $items("Get Orders");
const costs = $items("Get Costs");

let maxDate = new Date("2000-01-01");
orders.forEach(o => {
    if (o.json["Delivery Date"]) {
        let d = new Date(o.json["Delivery Date"]);
        if (d > maxDate) maxDate = d;
    }
});
let maxDateStr = maxDate.toISOString().substring(0, 10);
let currentMonthPrefix = maxDateStr.substring(0, 7);

let lastMonthDate = new Date(maxDate.getFullYear(), maxDate.getMonth() - 1, 1);
let lastMonthPrefix = lastMonthDate.toISOString().substring(0, 7);
let lastYearMonthPrefix = `${maxDate.getFullYear() - 1}-${String(maxDate.getMonth() + 1).padStart(2, '0')}`;

let oneWeekAgo = new Date(maxDate); oneWeekAgo.setDate(maxDate.getDate() - 7);
let twoWeeksAgo = new Date(maxDate); twoWeeksAgo.setDate(maxDate.getDate() - 14);

let report = {
    weekly:  { rev: 0, cost: 0, orders: 0, channels: {}, costs: {}, colors: {} },
    prevWeekly: { rev: 0, cost: 0, orders: 0 },
    monthly: { rev: 0, cost: 0, orders: 0, occasions: {}, channels: {}, costs: {}, freshQty: 0, wasteQty: 0 }, 
    lastMonthly: { rev: 0, cost: 0, orders: 0 },
    lastYearMonthly: { rev: 0, cost: 0, orders: 0 },
    yearly:  { rev: 0, cost: 0, orders: 0 }
};

let trendMonthly = {};
let trendColorMonthly = {}; 
let allColorsCount = {};
let wastageByItem = {}; // 用於統計各項花材的耗損量

// --- 處理 Orders ---
orders.forEach(order => {
    let dateStr = order.json["Delivery Date"];
    if (!dateStr) return;
    let d = new Date(dateStr);
    let rev = Number(order.json["Selling Price ($)"]) || 0;
    let monthStr = dateStr.substring(0, 7);

    report.yearly.rev += rev; report.yearly.orders += 1;
    if(!trendMonthly[monthStr]) trendMonthly[monthStr] = {rev: 0, cost: 0};
    trendMonthly[monthStr].rev += rev;

    let co = order.json["Main Colors"] || "Unknown";
    if(!trendColorMonthly[monthStr]) trendColorMonthly[monthStr] = {};
    trendColorMonthly[monthStr][co] = (trendColorMonthly[monthStr][co] || 0) + 1;
    allColorsCount[co] = (allColorsCount[co] || 0) + 1;

    if (dateStr.startsWith(currentMonthPrefix)) {
        report.monthly.rev += rev; report.monthly.orders += 1;
        let occ = order.json["Occasion"] || "Unknown";
        let ch = order.json["Sales Channel"] || "Unknown";
        report.monthly.occasions[occ] = (report.monthly.occasions[occ] || 0) + 1;
        report.monthly.channels[ch] = (report.monthly.channels[ch] || 0) + 1; 
    }
    if (dateStr.startsWith(lastMonthPrefix)) { report.lastMonthly.rev += rev; report.lastMonthly.orders += 1; }
    if (dateStr.startsWith(lastYearMonthPrefix)) { report.lastYearMonthly.rev += rev; report.lastYearMonthly.orders += 1; }

    if (d > oneWeekAgo && d <= maxDate) {
        report.weekly.rev += rev; report.weekly.orders += 1;
        report.weekly.colors[co] = (report.weekly.colors[co] || 0) + 1;
    }
    if (d > twoWeeksAgo && d <= oneWeekAgo) { report.prevWeekly.rev += rev; report.prevWeekly.orders += 1; }
});

// --- 處理 Costs (包含 Wastage 邏輯) ---
costs.forEach(cost => {
    let dateStr = cost.json["Purchase Date"];
    if (!dateStr) return;
    let d = new Date(dateStr);
    let cst = Number(cost.json["Total Cost ($)"]) || 0;
    let monthStr = dateStr.substring(0, 7);

    let itemName = cost.json["Item Name"] || "Unknown";
    let category = cost.json["Category"] || "Other";
    let qty = Number(cost.json["Quantity"]) || 0;
    let wasteQty = Number(cost.json["Wastage Qty"]) || 0;

    report.yearly.cost += cst;
    if(!trendMonthly[monthStr]) trendMonthly[monthStr] = {rev: 0, cost: 0};
    trendMonthly[monthStr].cost += cst;

    if (dateStr.startsWith(currentMonthPrefix)) {
        report.monthly.cost += cst;
        report.monthly.costs[category] = (report.monthly.costs[category] || 0) + cst;

        // 只統計鮮花類的耗損率，排除包裝耗材
        if (category === "Fresh Flower" || itemName.includes("Rose") || itemName.includes("Tulip") || itemName.includes("Gerbera") || itemName.includes("Carnation") || itemName.includes("Sunflower")) {
            report.monthly.freshQty += qty;
            report.monthly.wasteQty += wasteQty;

            let fullName = `${itemName} (${cost.json["Color/Variety"] || ""})`;
            wastageByItem[fullName] = (wastageByItem[fullName] || 0) + wasteQty;
        }
    }
    if (dateStr.startsWith(lastMonthPrefix)) report.lastMonthly.cost += cst;
    if (dateStr.startsWith(lastYearMonthPrefix)) report.lastYearMonthly.cost += cst;

    if (d > oneWeekAgo && d <= maxDate) report.weekly.cost += cst; 
    if (d > twoWeeksAgo && d <= oneWeekAgo) report.prevWeekly.cost += cst;
});

// --- Helper Functions ---
const getMargin = (rev, cost) => rev > 0 ? (((rev - cost) / rev) * 100).toFixed(1) : 0;
const calcVar = (curr, prev, inverseColor = false) => {
    if (prev == 0) return curr > 0 ? { str: "▲ +100%", color: inverseColor ? "#E74C3C" : "#10B981" } : { str: "- 0%", color: "#64748B" };
    let pct = ((curr - prev) / prev) * 100;
    let sign = pct > 0 ? "▲ +" : (pct < 0 ? "▼ " : "- ");
    let isPositive = pct >= 0;
    let color = isPositive ? (inverseColor ? "#E74C3C" : "#10B981") : (inverseColor ? "#10B981" : "#E74C3C");
    return { str: `${sign}${pct.toFixed(1)}%`, color: color };
};

report.weekly.margin = getMargin(report.weekly.rev, report.weekly.cost);
report.prevWeekly.margin = getMargin(report.prevWeekly.rev, report.prevWeekly.cost);
report.monthly.margin = getMargin(report.monthly.rev, report.monthly.cost);
report.lastMonthly.margin = getMargin(report.lastMonthly.rev, report.lastMonthly.cost);
report.lastYearMonthly.margin = getMargin(report.lastYearMonthly.rev, report.lastYearMonthly.cost);
report.monthly.spoilageRate = report.monthly.freshQty > 0 ? ((report.monthly.wasteQty / report.monthly.freshQty) * 100).toFixed(1) : 0;

report.weekly.topColor = Object.keys(report.weekly.colors).length > 0 ? Object.keys(report.weekly.colors).reduce((a, b) => report.weekly.colors[a] > report.weekly.colors[b] ? a : b) : "N/A";
report.monthly.top3Occasions = Object.keys(report.monthly.occasions).sort((a, b) => report.monthly.occasions[b] - report.monthly.occasions[a]).slice(0, 3).join(', ') || "N/A";

let wow = { rev: calcVar(report.weekly.rev, report.prevWeekly.rev), cost: calcVar(report.weekly.cost, report.prevWeekly.cost, true), margin: calcVar(report.weekly.margin, report.prevWeekly.margin), orders: calcVar(report.weekly.orders, report.prevWeekly.orders) };
let mom = { rev: calcVar(report.monthly.rev, report.lastMonthly.rev), cost: calcVar(report.monthly.cost, report.lastMonthly.cost, true), margin: calcVar(report.monthly.margin, report.lastMonthly.margin), orders: calcVar(report.monthly.orders, report.lastMonthly.orders) };
let yoy = { rev: calcVar(report.monthly.rev, report.lastYearMonthly.rev), cost: calcVar(report.monthly.cost, report.lastYearMonthly.cost, true), margin: calcVar(report.monthly.margin, report.lastYearMonthly.margin), orders: calcVar(report.monthly.orders, report.lastYearMonthly.orders) };

// --- 產生圖表 ---
let monthlyLabels = Object.keys(trendMonthly).sort();
let monthlyRevs = [], monthlyCosts = [], monthlyMargins = [];
monthlyLabels.forEach(l => { let r = trendMonthly[l].rev, c = trendMonthly[l].cost; monthlyRevs.push(r); monthlyCosts.push(c); monthlyMargins.push(r > 0 ? Number((((r-c)/r)*100).toFixed(1)) : 0); });
const urlTrendMonthly = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify({ type: 'bar', data: { labels: monthlyLabels, datasets: [ { type: 'line', label: 'Cash Margin (%)', data: monthlyMargins, borderColor: '#F59E0B', fill: false, yAxisID: 'y2' }, { type: 'bar', label: 'Cash In ($)', data: monthlyRevs, backgroundColor: '#3B82F6', yAxisID: 'y1' }, { type: 'bar', label: 'Cash Out ($)', data: monthlyCosts, backgroundColor: '#EF4444', yAxisID: 'y1' } ] }, options: { title: { display: true, text: 'Monthly Cash Flow Trend' }, scales: { yAxes: [ { id: 'y1', type: 'linear', position: 'left' }, { id: 'y2', type: 'linear', position: 'right', gridLines: { drawOnChartArea: false } } ] } } }))}`;

let occKeys = Object.keys(report.monthly.occasions).sort((a, b) => report.monthly.occasions[b] - report.monthly.occasions[a]);
const urlOccasion = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify({ type: 'horizontalBar', data: { labels: occKeys, datasets: [{ label: 'Orders', data: occKeys.map(k => report.monthly.occasions[k]), backgroundColor: '#64748B' }] }, options: { title: { display: true, text: 'MTD Occasion Distribution (Order Qty)' }, legend: { display: false }, scales: { xAxes: [{ ticks: { beginAtZero: true, stepSize: 1 } }] } } }))}`;

const urlChannel = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify({ type: 'pie', data: { labels: Object.keys(report.monthly.channels), datasets: [{ data: Object.values(report.monthly.channels), backgroundColor: ['#3B82F6', '#F59E0B'] }] }, options: { title: { display: true, text: 'MTD Channel' } } }))}`;
const urlCost = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify({ type: 'doughnut', data: { labels: Object.keys(report.monthly.costs), datasets: [{ data: Object.values(report.monthly.costs), backgroundColor: ['#EF4444', '#10B981', '#8B5CF6'] }] }, options: { title: { display: true, text: 'MTD Cost Structure' } } }))}`;

// 🌟 新增：Top 5 耗損花材圖表 (Inventory Wastage)
let topWastedItems = Object.keys(wastageByItem).sort((a, b) => wastageByItem[b] - wastageByItem[a]).slice(0, 5);
const urlWastage = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify({ type: 'bar', data: { labels: topWastedItems, datasets: [{ label: 'Wasted Stems (Qty)', data: topWastedItems.map(k => wastageByItem[k]), backgroundColor: '#EF4444' }] }, options: { title: { display: true, text: 'Top 5 Spoilage Items (MTD)' }, legend: { display: false }, scales: { yAxes: [{ ticks: { beginAtZero: true } }] } } }))}`;

const semanticColors = { 'Pink': '#F472B6', 'Red': '#EF4444', 'Blue': '#3B82F6', 'White': '#E2E8F0', 'Yellow': '#FBBF24', 'Purple': '#8B5CF6', 'Orange': '#F97316', 'Peach': '#FDBA74', 'Champagne': '#FEF3C7', 'Green': '#10B981' };
let top5Colors = Object.keys(allColorsCount).sort((a,b) => allColorsCount[b] - allColorsCount[a]).slice(0, 5);
let colorDatasets = top5Colors.map((col) => { return { label: col, data: monthlyLabels.map(m => trendColorMonthly[m][col] || 0), backgroundColor: semanticColors[col] || '#94A3B8' }; });
const urlSeasonalColor = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify({ type: 'bar', data: { labels: monthlyLabels, datasets: colorDatasets }, options: { title: { display: true, text: 'Seasonal Color Demand' }, scales: { xAxes: [{ stacked: true }], yAxes: [{ stacked: true }] } } }))}`;

let currentTopColor = top5Colors.map(c => `${c}:${trendColorMonthly[currentMonthPrefix]?.[c]||0}`).join(', ');

return [{
  json: {
    report, wow, mom, yoy, currentTopColor,
    urlChannel, urlCost, urlTrendMonthly, urlOccasion, urlSeasonalColor, urlWastage,
    latestDate: maxDateStr
  }
}];
